# .github/workflows/ios-build.yml
name: Build iOS App

on:
  workflow_dispatch:
  repository_dispatch:
    types: [build-ios]

jobs:
  build:
    runs-on: macos-14
    steps:
    - name: Checkout code
      uses: actions/checkout@v4
      with:
        fetch-depth: 0

    - name: Select Xcode version
      uses: maxim-lobanov/setup-xcode@v1
      with:
        xcode-version: 'latest-stable'

    - name: Create Xcode project
      run: |
        cd MyApp
        mkdir -p MyApp.xcodeproj/xcshareddata/xcschemes
        cat > MyApp.xcodeproj/project.pbxproj << 'EOF'
        // !$*UTF8*$!
        {
          archiveVersion = 1;
          classes = {
          };
          objectVersion = 56;
          objects = {
EOF

    - name: Build and Archive
      run: |
        cd MyApp
        mkdir -p build
        xcodebuild clean archive \
          -project MyApp.xcodeproj \
          -scheme MyApp \
          -sdk iphoneos \
          -configuration Release \
          -archivePath build/MyApp.xcarchive \
          -derivedDataPath build \
          CODE_SIGN_IDENTITY="" \
          CODE_SIGNING_REQUIRED=NO \
          CODE_SIGNING_ALLOWED=NO \
          DEVELOPMENT_TEAM="" \
          PROVISIONING_PROFILE_SPECIFIER="" \
          ONLY_ACTIVE_ARCH=NO

    - name: Export IPA
      run: |
        cd MyApp
        rm -rf Payload
        mkdir -p Payload
        ditto -ck --rsrc --sequesterRsrc --keepParent build/MyApp.xcarchive/Products/Applications/MyApp.app Payload/MyApp.app
        zip -r ../MyApp.ipa Payload
        ls -la ../MyApp.ipa
        file ../MyApp.ipa

    - name: Upload IPA artifact
      uses: actions/upload-artifact@v4
      with:
        name: MyApp-IPA-${{ github.run_number }}
        path: MyApp/MyApp.ipa
        retention-days: 7
        compression-level: 0
